  "auth.role": { de: "Rolle", en: "Role" },
  "auth.rolesHelp": { de: "Viewer: lesen und lokal kalkulieren. Admin: Drucke, Dokumente und normale Einstellungen bearbeiten. Superadmin: zusätzlich Benutzer, Rollen, Datenbank, Verbindungen und API-Schlüssel verwalten. Custom-Rollen erhalten einzeln auswählbare Rechte; benötigte Leserechte werden ergänzt. Benutzerverwaltung bleibt Superadmins vorbehalten.", en: "Viewer: read and calculate locally. Admin: edit prints, documents and regular settings. Superadmin: additionally manage users, roles, database, connections and API keys. Custom roles have selectable permissions; required read permissions are added. User management is reserved for superadmins." },
  "auth.userPasswordHelp": { de: "Neue und zurückgesetzte Passwörter müssen den gespeicherten Passwortregeln entsprechen und beim nächsten Login geändert werden. Bearbeiten widerruft Sitzungen und API-Schlüssel. Eigene Zugangsdaten über das Benutzermenü (Klick auf den Benutzernamen) ändern.", en: "New and reset passwords must meet the saved password requirements and be changed at the next login. Editing revokes sessions and API keys. Change your own credentials via the user menu (click your username)." },
  "auth.policy.title": { de: "Passwortregeln", en: "Password requirements" },
  "auth.policy.help": { de: "Gilt für neue, zurückgesetzte und geänderte Passwörter. Bestehende Passwörter bleiben gültig. Mindestlänge: 4–128 Zeichen. Das Startpasswort „admin“ bleibt ausgeschlossen.", en: "Applies to new, reset and changed passwords. Existing passwords remain valid. Minimum length: 4–128 characters. The initial password “admin” remains disallowed." },
